INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('215', 'HBL_HIMAL_REMIT_FD_REQUEST', '<p>&nbsp;</p><center><img src=\"https://ib1.himalayanbank.com/images/brand-login.png\" alt=\"hbl_logo\"  style=\"width:550px; display: block; margin-left: auto; margin-right: auto;\"/><br /><br /> <br /><table align=\"center\" style=\"width: 600px;\" ><tr><td style=\"border-style: solid; border-width: 6px; border-color: black;\"><br /><p  style=\"margin-left: 10px;\"> Dear Branch Manager,<br /><br /> %firstName% %lastName% with Account Number %accountNumber% has requested to open Himal Remit FD Account with (Ref no:%refNumber%). The request is awaiting on your approval. Please do the needful at the earliest.<br/><br/> Regards, <br/>Himalayan Bank Limited.<br/></center></p><br /><br /><br /></td></tr><tr><td><br /><b>Auto-generated Email Notification. Please do not reply to this email address.</b> <br /><br />The information in this mail is confidential and is intended solely for the addressee. Access to this mail by anyone else is unauthorized. Copying or further distribution beyond the original recipient may be unlawful. <br /><br /></td></tr></table></center>', 'Himal Remit FD Request', 'Infinity', 'dbx_cl@infinity.com');
INSERT INTO `dbxdb`.`emailtemplates` (`id`, `TemplateName`, `TemplateText`, `Subject`, `SenderName`, `SenderEmail`) VALUES ('216', 'HBL_RESET_TRANSACTION_PIN', '<p>&nbsp;</p><center><img src=\"https://ib1.himalayanbank.com/images/brand-login.png\" alt=\"hbl_logo\"  style=\"width:550px; display: block; margin-left: auto; margin-right: auto;\"/><br /><br /> <br /><table align=\"center\" style=\"width: 600px;\" ><tr><td style=\"border-style: solid; border-width: 6px; border-color: black;\"><br /><p  style=\"margin-left: 10px;\"> RESET TRANSACTION PIN NOTIFICATION <br /><br />Dear %firstName%,<br /><br />You are enrolled to Digital Banking Channel. Please activate your account now.<br /><br />%userName% is your username. Activation code is %otp% sent to your registered mobile number.<br /><br />You are required to input your username &amp; activation code in the link below.<br /><br /><center>To activate your account and set a password,<a style=\"color: #11abeb;\" href=\"%resetPasswordLink%\">click here</a> <br />or paste the following link on your browser: <br /><br /><a style=\"color: #11abeb;\">%resetPasswordLink%</a><br/><br/>The activation code will expire in %activationCodeExpiry% days , so activate it right away.</center></p><br /><br /><br /></td></tr><tr><td><br /><b>Auto-generated Email Notification. Please do not reply to this email address.</b> <br /><br />The information in this mail is confidential and is intended solely for the addressee. Access to this mail by anyone else is unauthorized. Copying or further distribution beyond the original recipient may be unlawful. <br /><br /></td></tr></table></center>', 'Reset Transaction PIN', 'Infinity', 'dbx_cl@infinity.com');
